export function burst(e){for(let k=0;k<10;k++){const s=document.createElement("div");s.className="star";s.textContent="⭐";const r=e.getBoundingClientRect();s.style.left=r.left+r.width/2+"px";s.style.top=r.top+r.height/2+"px";s.style.setProperty("--x",(Math.random()-.5)*300+"px");s.style.setProperty("--y",(Math.random()-.8)*260+"px");document.body.appendChild(s);setTimeout(()=>s.remove(),1000)}}
